/bin/bash -lc 'project=MainProjects/Algebraic-Jacobian-Challenge
declare -A ids=()
while IFS= read -r p; do b=${p##*/}; ids[${b%.md}]=1; done < <(rg -l "''^chapter: '"'Adelic Riemann--Roch\" \""'$project/hgraph/nodes")
while IFS= read -r p; do b=${p##*/}; ids[${b%.md}]=1; done < <(rg -l '"'"'^file: AlgebraicJacobian/RiemannRoch/Adelic/(ChiLedger|GateInstances|FinitenessP1|GenusUnconditional)'"\\.lean"'$'"' \""'$project/hgraph/nodes")
selected=()
while IFS= read -r line; do
  p=${line:3}
  case "$p" in
    "$project"/hgraph/nodes/*.md)
      b=${p##*/}; id=${b%.md}; [[ ${ids[$id]+x} ]] && selected+=("$p") ;;
    "$project"/hgraph/edges/*.md)
      b=${p##*/}; b=${b%.md}; s=${b%%__*}; t=${b##*__};
      [[ ${ids[$s]+x} || ${ids[$t]+x} ]] && selected+=("$p") ;;
  esac
done < <(/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/bin/hgit status --porcelain -- "$project/hgraph")
printf '"'selected=%s\\n' \""'${#selected[@]}"
printf '"'%s\\n' \""'${selected[@]}"'

